<?php require "includes.php";$rows=$pdo->query("SELECT * FROM galeri ORDER BY tahun DESC,id DESC")->fetchAll();?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Galeri | HMPSIF</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="assets/css/style_modern.css" rel="stylesheet"></head><body><?php include "navbar.php";?><main class="section"><div class="container"><div class="eyebrow">Dokumentasi Visual</div><h1 class="section-title mb-5">Galeri Kegiatan</h1><div class="row g-3"><?php foreach($rows as $r):?><div class="col-6 col-lg-3"><a href="<?=e($r["foto"])?>" data-bs-toggle="modal" data-bs-target="#lightbox"><img src="<?=e($r["foto"])?>" class="gallery-img rounded-4" alt="<?=e($r["judul"])?>"></a></div><?php endforeach;?></div></div></main><div class="modal fade" id="lightbox"><div class="modal-dialog modal-xl modal-dialog-centered"><div class="modal-content bg-dark"><img id="lightboxImg" class="w-100 rounded" src=""></div></div></div><?php include "footer.php";?><script>document.querySelectorAll(".gallery-img").forEach(i=>i.onclick=()=>document.getElementById("lightboxImg").src=i.src)</script></body></html>